            for j in range(i, n):
                matrix[j][pivot_col] /= matrix[i][pivot_col]
            rank += 1
            for j in range(n):
                if j == i:
                    continue
                factor = matrix[j][pivot_col]
                for k in range(n):
                    matrix[j][k] -= factor * matrix[i][k]
        return rank

